const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults=[{id:'noir',name:'Éclipse',price:189000,category:'Длинные',color:'Горький шоколад',sizes:'40, 42, 44, 46',description:'Выразительный длинный силуэт с объёмным воротником. Глубокий шоколадный оттенок для образов, которые остаются в памяти.',image:'assets/hero.png'},{id:'ivory',name:'Sable',price:149000,category:'Укороченные',color:'Тёплый карамельный',sizes:'40, 42, 44, 46, 48',description:'Расслабленная посадка, мягкая линия плеча и укороченный силуэт. Ваш акцент в повседневном гардеробе.',image:'assets/hero.png'},{id:'terre',name:'Terre',price:99000,category:'Эко-мех',color:'Кофейный',sizes:'42, 44, 46, 48',description:'Объёмная модель из эко-меха с выразительной фактурой. Мягкость и уют в каждой детали.',image:'assets/hero.png'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let products=read('velour-products',defaults),wishes=read('velour-wishes',[]),filter='all';
if(!Array.isArray(products))products=defaults;products=products.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&Number.isFinite(p.price)&&p.price>0&&typeof p.sizes==='string'&&typeof p.image==='string'&&typeof p.category==='string'&&typeof p.color==='string'&&typeof p.description==='string');if(!Array.isArray(wishes))wishes=[];
const newPhotos={noir:'assets/collection.png#left',ivory:'assets/collection.png#middle',terre:'assets/collection.png#right'};
products=products.map(p=>newPhotos[p.id]&&p.image==='assets/hero.png'?{...p,image:newPhotos[p.id],...(p.id==='terre'?{color:'Молочный'}:{})}:p);
const addedModels=[{"id":"ambre","name":"Ambre","price":215000,"category":"Длинные","color":"Эспрессо","description":"Длинная шуба с поясом и выразительным воротником. Глубокий оттенок эспрессо подчёркивает строгие линии силуэта.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile0"},{"id":"nuage","name":"Nuage","price":89000,"category":"Эко-мех","color":"Сливочный","description":"Укороченная модель из светлого эко-меха. Лёгкий объём и свободная посадка для расслабленных зимних образов.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile1"},{"id":"cannelle","name":"Cannelle","price":159000,"category":"Миди","color":"Карамель","description":"Шуба длины миди в тёплом карамельном оттенке. Мягкий воротник и прямой крой.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile2"},{"id":"brume","name":"Brume","price":229000,"category":"Длинные","color":"Тауп","description":"Удлинённая модель с объёмным воротником. Сложный серо-бежевый оттенок для сдержанного гардероба.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile3"},{"id":"cacao","name":"Cacao","price":139000,"category":"Укороченные","color":"Какао","description":"Компактный силуэт и объёмные рукава. Шоколадный оттенок сочетается с молочной палитрой.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile4"},{"id":"neige","name":"Neige","price":119000,"category":"Эко-мех","color":"Белый жемчуг","description":"Длинная шуба из светлого эко-меха с широким воротником. Свободная посадка для многослойных образов.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile5"},{"id":"miel","name":"Miel","price":179000,"category":"Миди","color":"Медовый","description":"Модель миди с поясом, подчёркивающим талию. Тёплый медовый оттенок и мягкая линия плеч.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile6"},{"id":"lune","name":"Lune","price":199000,"category":"Миди","color":"Серебристый","description":"Шуба длины до колена в серебристо-сером оттенке. Лаконичный крой и выразительная фактура.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile7"},{"id":"opera","name":"Opéra","price":269000,"category":"Длинные","color":"Тёмный шоколад","description":"Максимальная длина и объёмный воротник. Эффектная шоколадная модель для особенных выходов.","sizes":"40, 42, 44, 46, 48","image":"assets/new-collection.png#tile8"}];
if(!read('velour-expanded-collection',false)){for(const model of addedModels){if(!products.some(p=>p.id===model.id))products.push(model)}try{localStorage.setItem('velour-products',JSON.stringify(products));localStorage.setItem('velour-expanded-collection','true')}catch{}}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('velour-products',JSON.stringify(products));return true}catch{toast('Недостаточно памяти. Выберите фотографию меньшего размера.');return false}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
function observe(){$$('.reveal:not(.visible)').forEach((el,i)=>{el.style.transitionDelay=`${i%3*80}ms`;observer.observe(el)})}
function render(){const catalogState=window.velourCatalogState||{query:'',sort:'featured'};const shown=products.filter(p=>(filter==='all'||p.category===filter)&&(!catalogState.query||(p.name+' '+p.color+' '+p.category).toLocaleLowerCase('ru').includes(catalogState.query.toLocaleLowerCase('ru')))).sort((a,b)=>catalogState.sort==='price-up'?a.price-b.price:catalogState.sort==='price-down'?b.price-a.price:catalogState.sort==='name'?a.name.localeCompare(b.name,'ru'):0);$('#products').innerHTML=shown.length?shown.map((p,i)=>`<article class="product reveal"><div class="product-image"><button class="product-open" data-product="${esc(p.id)}" aria-label="Открыть ${esc(p.name)}"><img src="${esc(p.image)}" alt="Шуба ${esc(p.name)}, ${esc(p.color)}" loading="lazy"></button><span class="product-tag">${i===0?'ВЫБОР VELOUR':'КОЛЛЕКЦИЯ 2026'}</span><button class="heart ${wishes.includes(p.id)?'saved':''}" data-wish="${esc(p.id)}" aria-label="Добавить в избранное" aria-pressed="${wishes.includes(p.id)}">${wishes.includes(p.id)?'♥':'♡'}</button><span class="view-model">ПОЗНАКОМИТЬСЯ БЛИЖЕ ↗</span></div><div class="product-info"><div><h3>${esc(p.name)}</h3><p>${esc(p.color)} / ${esc(p.category)}</p></div><span class="price">${money(p.price)}</span></div><button class="compare-model" data-compare="${esc(p.id)}" aria-pressed="false">＋ Сравнить модель</button></article>`).join(''):'<p class="empty">Модели не найдены. Попробуйте изменить поиск или категорию.</p>';$('#productCount').textContent=shown.length+' '+(shown.length%10===1&&shown.length%100!==11?'модель':shown.length%10>=2&&shown.length%10<=4&&(shown.length%100<12||shown.length%100>14)?'модели':'моделей');$('#bagCount').textContent=wishes.filter(id=>products.some(p=>p.id===id)).length;document.dispatchEvent(new Event('velour:catalog-changed'));observe()}
function openProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('#productDetail').innerHTML=`<div class="detail-grid"><div class="detail-photo"><img src="${esc(p.image)}" alt="${esc(p.name)}"></div><div><p class="eyebrow">${esc(p.category)} / VELOUR</p><h2>${esc(p.name)}</h2><h3>${money(p.price)}</h3><p>${esc(p.description)}</p><p>Оттенок: ${esc(p.color)}</p><div class="sizes">${p.sizes.split(',').map(s=>`<button data-size>${esc(s.trim())}</button>`).join('')}</div><button class="button dark" id="tryProduct">Примерить эту модель ↗</button></div></div>`;$('#productDialog').showModal();$('#tryProduct').onclick=()=>{$('#productDialog').close();if($('#wishDialog').open)$('#wishDialog').close();$('#appointmentDialog').showModal()}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-product]');if(p)openProduct(p.dataset.product);const w=e.target.closest('[data-wish]');if(w){wishes=wishes.includes(w.dataset.wish)?wishes.filter(x=>x!==w.dataset.wish):[...wishes,w.dataset.wish];try{localStorage.setItem('velour-wishes',JSON.stringify(wishes))}catch{}render()}const size=e.target.closest('[data-size]');if(size){$$('[data-size]').forEach(b=>b.classList.remove('selected'));size.classList.add('selected')}if(e.target.closest('[data-close]'))e.target.closest('dialog').close()});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});
$('#bagButton').onclick=()=>{$('#wishList').innerHTML=wishes.map(id=>products.find(p=>p.id===id)).filter(Boolean).map(p=>`<div class="admin-row"><span>${esc(p.name)} — ${money(p.price)}</span><button data-product="${esc(p.id)}">Посмотреть ↗</button></div>`).join('')||'<p class="empty">Сохраните модели, которые вам понравились, с помощью ♡ в коллекции.</p>';$('#wishDialog').showModal()};
$('#appointmentButton').onclick=()=>$('#appointmentDialog').showModal();
$('#appointmentForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{localStorage.setItem('velour-appointment',JSON.stringify(data));$('#appointmentDialog').close();e.target.reset();toast('Запись сохранена на этом устройстве. В салон она не отправлена.')}catch{toast('Браузер не разрешил сохранить запись.')}};
$('#appointmentForm [name=date]').min=new Date().toLocaleDateString('en-CA');
function renderAdmin(){$('#adminList').innerHTML=products.map(p=>`<div class="admin-row"><span>${esc(p.name)} · ${money(p.price)}</span><div><button data-edit="${esc(p.id)}">Изменить</button> <button data-delete="${esc(p.id)}">Удалить</button></div></div>`).join('')||'<p>Добавьте первую модель.</p>'}
$('#adminButton').onclick=()=>{renderAdmin();$('#adminDialog').showModal()};$('#resetForm').onclick=()=>{$('#productForm').reset();$('#productForm [name=id]').value=''};
$('#adminList').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit){const p=products.find(x=>x.id===edit.dataset.edit);for(const key of ['id','name','price','category','color','sizes','description'])$('#productForm').elements[key].value=p[key];$('#productForm').scrollIntoView({behavior:'smooth',block:'start'})}if(del&&confirm('Удалить модель из коллекции?')){const before=products;products=products.filter(p=>p.id!==del.dataset.delete);if(!persist())products=before;render();renderAdmin()}};
async function photoData(file){if(!file.type.startsWith('image/'))throw Error('Выберите файл изображения.');if(file.size>15*1024*1024)throw Error('Фотография должна быть меньше 15 МБ.');const bmp=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,1200/bmp.width,1600/bmp.height);canvas.width=bmp.width*ratio;canvas.height=bmp.height*ratio;canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close();return canvas.toDataURL('image/jpeg',.82)}
$('#productForm').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=f.querySelector('[type=submit]');btn.disabled=true;try{const data=Object.fromEntries(new FormData(f));if(!data.name.trim()||!data.color.trim()||!data.description.trim())throw Error('Заполните название, цвет и описание — не только пробелами.');if(!/^\s*\d{2,3}\s*(,\s*\d{2,3}\s*)*$/.test(data.sizes))throw Error('Укажите размеры числами через запятую, например: 40, 42, 44.');const old=products.find(x=>x.id===data.id);const image=data.photo.size?await photoData(data.photo):old?.image||'assets/hero.png';const p={id:old?.id||crypto.randomUUID(),name:data.name.trim(),price:Number(data.price),category:data.category,color:data.color.trim(),sizes:data.sizes.trim(),description:data.description.trim(),image};const before=products;products=old?products.map(x=>x.id===p.id?p:x):[...products,p];if(!persist()){products=before;return}render();renderAdmin();f.reset();f.elements.id.value='';toast('Модель сохранена и добавлена в коллекцию')}catch(err){toast(err.message||'Не удалось сохранить модель.')}finally{btn.disabled=false}};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(max>0?scrollY/max*100:0)+'%';if(!reduced&&scrollY<innerHeight*1.5)$('#heroImage').style.setProperty('--hero-parallax',`${scrollY*.22}px`);ticking=false})},{passive:true});
render();observe();
const ribbon=document.createElement('div');ribbon.className='motion-ribbon';ribbon.setAttribute('aria-label','VELOUR — искусство тепла, новая коллекция');const ribbonContent='<span>THE ART OF WARMTH</span><i>✳</i><em>Тепло, которое вдохновляет</em><i>✳</i><span>VELOUR — NEW COLLECTION</span><i>✳</i>';ribbon.innerHTML='<div class="ribbon-track" aria-hidden="true"><div class="ribbon-group">'+ribbonContent+'</div><div class="ribbon-group">'+ribbonContent+'</div></div>';$('.hero').after(ribbon);
const scrollLink=$('.hero-bottom a');scrollLink.innerHTML='Листайте, чтобы почувствовать <span class="scroll-orbit" aria-hidden="true">↓</span>';
const motionToggle=document.createElement('button');motionToggle.className='motion-toggle';motionToggle.innerHTML='<span>Ⅱ</span> Остановить движение';motionToggle.setAttribute('aria-pressed','false');document.body.append(motionToggle);motionToggle.onclick=()=>{const paused=document.body.classList.toggle('motion-paused');motionToggle.innerHTML=paused?'<span>▶</span> Включить движение':'<span>Ⅱ</span> Остановить движение';motionToggle.setAttribute('aria-pressed',String(paused))};
if(!reduced&&matchMedia('(pointer:fine)').matches){$('#products').addEventListener('pointermove',e=>{const card=e.target.closest('.product');if(!card)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`rotateY(${x*6}deg) rotateX(${-y*5}deg) translateY(-8px)`});$('#products').addEventListener('pointerout',e=>{const card=e.target.closest('.product');if(card&&!card.contains(e.relatedTarget))card.style.transform=''})}

const edgeAmbient=document.createElement('div');edgeAmbient.className='edge-ambient';edgeAmbient.setAttribute('aria-hidden','true');edgeAmbient.innerHTML='<span class="edge-rail left"></span><span class="edge-rail right"></span><span class="edge-star one">✳</span><span class="edge-star two">✳</span><span class="edge-star three">✦</span><span class="edge-glow"></span><span class="edge-glow other"></span><span class="edge-label">VELOUR — THE ART OF WARMTH</span><span class="edge-label right">MAISON DE FOURRURE — 2026</span>';document.body.append(edgeAmbient);
